// Extract 2FA code and build the response message
const items = $input.all();
const userName = $('Form Trigger').first().json['Full Name'] || 'User';

let code = null;
let emailSubject = '';
let emailFrom = '';

for (const item of items) {
  const body = item.json.snippet || item.json.textPlain || item.json.text || item.json.body || '';
  emailSubject = item.json.subject || '';
  emailFrom = item.json.from || '';

  // Strategy 1: Code/OTP patterns near keywords
  const keywordPatterns = [
    /(?:verification|verify|security|confirmation|login|access|authentication|sign[- ]?in|one[- ]?time)\s*(?:code|pin|OTP|number)[\s:]*[\(\[]?\s*([A-Z0-9]{4,8})\s*[\)\]]?/i,
    /(?:code|pin|OTP|token)[\s:]+[\(\[]?\s*([A-Z0-9]{4,8})\s*[\)\]]?/i,
    /(?:enter|use|input|submit|type)\s+(?:the\s+)?(?:code\s+)?[\(\[]?\s*([0-9]{4,8})\s*[\)\]]?/i,
    /\b([0-9]{4,8})\b(?=.*(?:expires?|valid|minutes?|mins?))/i,
    /(?:is|:|=)\s*\*?\s*([0-9]{4,8})\s*\*?/i
  ];

  for (const pattern of keywordPatterns) {
    const match = body.match(pattern);
    if (match && match[1]) {
      code = match[1];
      break;
    }
  }

  // Strategy 2: Code in subject line
  if (!code) {
    const subjectMatch = emailSubject.match(/\b([0-9]{4,8})\b/);
    if (subjectMatch && subjectMatch[1]) {
      code = subjectMatch[1];
    }
  }

  // Strategy 3: Standalone 6-digit number
  if (!code) {
    const standaloneMatch = body.match(/(?:^|\s)([0-9]{6})(?:\s|$|\.|,)/m);
    if (standaloneMatch && standaloneMatch[1]) {
      code = standaloneMatch[1];
    }
  }

  if (code) break;
}

// Build the response message
let message;
if (code) {
  message = 'Hi ' + userName + '!';
  message += '\n\n=============================';
  message += '\n   YOUR CODE:  ' + code;
  message += '\n=============================';
  message += '\n\nGo enter this code now — it expires in a few minutes.';
  message += '\n\nIf this code doesn\'t work, you may need to request a new one from the platform and submit this form again.';
} else {
  message = 'Hi ' + userName + ',';
  message += '\n\nWe couldn\'t find a verification code just yet.';
  message += '\n\nThis usually happens when:';
  message += '\n\n  1. The email is still on its way — wait about 30 seconds and try again';
  message += '\n  2. The code already expired — go back to the platform, request a new code, then submit this form immediately';
  message += '\n\nStill not working? Reach out to the admin for help.';
}

return { message: message };
